import Foundation

// A creation is a lightweight recipe: stable media identifiers, a layout style, and
// a seed. Geometry is regenerated by the Rust engine, so projects stay tiny, survive
// library changes, and render identically at preview and print resolutions.
struct CreationProject: Identifiable, Codable, Hashable, Sendable {
    enum Kind: String, Codable, CaseIterable, Sendable {
        case collage
        case photobook
        var title: String {
            switch self {
            case .collage: "Collage"
            case .photobook: "Photobook"
            }
        }
        var symbol: String {
            switch self {
            case .collage: "square.on.square.dashed"
            case .photobook: "book.closed"
            }
        }
    }

    var id = UUID()
    var kind: Kind
    var title: String
    var subtitle = ""
    var itemIDs: [String] = []
    var style: String
    var aspect: Double
    var seed: UInt64
    var spacing: Double
    var padding: Double
    var finish: CollageFinish
    var cornerRadius: Double
    var showCaptions = false
    // Photobook-only settings are harmless on a collage and keep one project type.
    var spread = true
    var pageAspect: Double = PageAspect.a4Portrait.value
    var maxPerPage = 4
    var includeCover = true
    // Optional so projects saved before these fields still decode. The accessors
    // below supply the defaults used by the studio.
    var story: String?
    var coverItemID: String?
    var eventTitles: [String: String]?
    var usePlaceNames: Bool?
    var createdAt = Date()
    var updatedAt = Date()

    static func suggestedTitle(_ kind: Kind) -> String {
        "\(kind.title) · \(Date.now.formatted(.dateTime.month(.abbreviated).day()))"
    }

    static func collage(itemIDs: [String], title: String = "Untitled collage") -> CreationProject {
        CreationProject(
            kind: .collage, title: title, itemIDs: itemIDs,
            style: CollageStyle.mosaic.rawValue, aspect: CollageAspect.square.value,
            seed: 1, spacing: 0.018, padding: 0.035, finish: .paper, cornerRadius: 10)
    }

    static func photobook(itemIDs: [String], title: String = "Untitled book") -> CreationProject {
        CreationProject(
            kind: .photobook, title: title, itemIDs: itemIDs,
            style: BookStyle.editorial.rawValue, aspect: 1.0, seed: 1,
            spacing: 0.016, padding: 0.03, finish: .paper, cornerRadius: 0,
            spread: true, pageAspect: PageAspect.a4Portrait.value, maxPerPage: 4, includeCover: true)
    }

    var storyFocus: String {
        get { story ?? "" }
        set { story = newValue }
    }

    var placeNamesEnabled: Bool {
        get { usePlaceNames ?? true }
        set { usePlaceNames = newValue }
    }

    var collageStyle: CollageStyle {
        get { CollageStyle(rawValue: style) ?? .mosaic }
        set { style = newValue.rawValue }
    }

    var bookStyle: BookStyle {
        get { BookStyle(rawValue: style) ?? .editorial }
        set { style = newValue.rawValue }
    }

    var collageAspect: CollageAspect {
        get { CollageAspect.nearest(aspect) }
        set { aspect = newValue.value }
    }

    var pageAspectChoice: PageAspect {
        get { PageAspect.nearest(pageAspect) }
        set { pageAspect = newValue.value }
    }
}

enum CollageStyle: String, Codable, CaseIterable, Identifiable, Sendable {
    case mosaic, grid, hero, magazine, filmstrip, scatter, stack, triptych
    var id: String { rawValue }
    var title: String {
        switch self {
        case .mosaic: "Mosaic"
        case .grid: "Grid"
        case .hero: "Hero"
        case .magazine: "Editorial"
        case .filmstrip: "Filmstrip"
        case .scatter: "Scatter"
        case .stack: "Stack"
        case .triptych: "Triptych"
        }
    }
    var symbol: String {
        switch self {
        case .mosaic: "square.grid.2x2"
        case .grid: "square.grid.3x3"
        case .hero: "rectangle.leadinghalf.inset.filled"
        case .magazine: "rectangle.split.3x1"
        case .filmstrip: "rectangle.split.2x1"
        case .scatter: "square.on.square.dashed"
        case .stack: "rectangle.stack"
        case .triptych: "rectangle.split.3x1.fill"
        }
    }
    var explanation: String {
        switch self {
        case .mosaic: "Asymmetric tiles that fill every corner."
        case .grid: "Calm, even rows."
        case .hero: "One large photograph leads."
        case .magazine: "Editorial rows with varied widths."
        case .filmstrip: "Two bands of cinematic crops."
        case .scatter: "Loose prints with a hand-placed feel."
        case .stack: "A layered pile, newest on top."
        case .triptych: "Three columns, or three rows when needed."
        }
    }
}

enum CollageAspect: String, Codable, CaseIterable, Identifiable, Sendable {
    case square, portrait, story, landscape, print
    var id: String { rawValue }
    var title: String {
        switch self {
        case .square: "Square"
        case .portrait: "Portrait"
        case .story: "Story"
        case .landscape: "Landscape"
        case .print: "Print 5:7"
        }
    }
    var value: Double {
        switch self {
        case .square: 1.0
        case .portrait: 0.8
        case .story: 0.5625
        case .landscape: 1.5
        case .print: 0.714
        }
    }
    static func nearest(_ value: Double) -> CollageAspect {
        allCases.min(by: { abs($0.value - value) < abs($1.value - value) }) ?? .square
    }
}

enum PageAspect: String, Codable, CaseIterable, Identifiable, Sendable {
    case a4Portrait, a4Landscape, square, letter
    var id: String { rawValue }
    var title: String {
        switch self {
        case .a4Portrait: "A4 portrait"
        case .a4Landscape: "A4 landscape"
        case .square: "Square"
        case .letter: "Letter"
        }
    }
    var value: Double {
        switch self {
        case .a4Portrait: 0.707
        case .a4Landscape: 1.414
        case .square: 1.0
        case .letter: 0.773
        }
    }
    static func nearest(_ value: Double) -> PageAspect {
        allCases.min(by: { abs($0.value - value) < abs($1.value - value) }) ?? .a4Portrait
    }
}

enum BookStyle: String, Codable, CaseIterable, Identifiable, Sendable {
    case editorial, classic, airy
    var id: String { rawValue }
    var title: String {
        switch self {
        case .editorial: "Editorial"
        case .classic: "Classic"
        case .airy: "Airy"
        }
    }
    var explanation: String {
        switch self {
        case .editorial: "A rhythm of quiet and dense pages."
        case .classic: "Even grids with generous photos."
        case .airy: "Fewer photos per page, larger moments."
        }
    }
}

enum CollageFinish: String, Codable, CaseIterable, Identifiable, Sendable {
    case paper, ink, white, sand, accent
    var id: String { rawValue }
    var title: String {
        switch self {
        case .paper: "Paper"
        case .ink: "Ink"
        case .white: "White"
        case .sand: "Sand"
        case .accent: "Aurora"
        }
    }
    /// Used by the SwiftUI preview and the Core Graphics exporter; keeping one
    /// definition prevents a project from changing color when it is shared.
    var components: (r: Double, g: Double, b: Double) {
        switch self {
        case .paper: (0.965, 0.961, 0.945)
        case .ink: (0.055, 0.055, 0.06)
        case .white: (1, 1, 1)
        case .sand: (0.886, 0.851, 0.80)
        case .accent: (0.12, 0.075, 0.16)
        }
    }
    var foregroundIsLight: Bool { self == .ink || self == .accent }
}

@MainActor @Observable
final class CreationStore {
    private(set) var projects: [CreationProject] = []
    private let url: URL

    init(url: URL? = nil) {
        self.url = url ?? Self.defaultURL()
        load()
    }

    private static func defaultURL() -> URL {
        let root = URL.applicationSupportDirectory.appending(path: "Mosaic", directoryHint: .isDirectory)
        try? FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
        return root.appending(path: "creations.json")
    }

    func project(id: UUID) -> CreationProject? {
        projects.first { $0.id == id }
    }

    @discardableResult
    func save(_ project: CreationProject) -> CreationProject {
        var saved = project
        saved.updatedAt = Date()
        if let index = projects.firstIndex(where: { $0.id == saved.id }) {
            projects[index] = saved
        } else {
            projects.append(saved)
        }
        projects.sort { $0.updatedAt > $1.updatedAt }
        persist()
        return saved
    }

    @discardableResult
    func add(_ itemIDs: [String], to projectID: UUID) -> CreationProject? {
        guard var project = project(id: projectID) else { return nil }
        var known = Set(project.itemIDs)
        for id in itemIDs where known.insert(id).inserted {
            // A book's order is its story order, so appended items go at the end
            // until the person explicitly reorders them.
            project.itemIDs.append(id)
        }
        return save(project)
    }

    func rename(_ project: CreationProject, to title: String) {
        var updated = project
        let cleaned = title.trimmingCharacters(in: .whitespacesAndNewlines)
        updated.title = cleaned.isEmpty ? project.kind.title : cleaned
        save(updated)
    }

    func delete(_ project: CreationProject) {
        projects.removeAll { $0.id == project.id }
        persist()
    }

    func duplicate(_ project: CreationProject) {
        var copy = project
        copy.id = UUID()
        copy.title = "\(project.title) copy"
        copy.createdAt = Date()
        copy.updatedAt = Date()
        projects.append(copy)
        persist()
    }

    private func load() {
        guard let data = try? Data(contentsOf: url) else { return }
        if let decoded = try? JSONDecoder().decode([CreationProject].self, from: data) {
            projects = decoded.sorted { $0.updatedAt > $1.updatedAt }
        }
    }

    private func persist() {
        do {
            try FileManager.default.createDirectory(
                at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
            let data = try JSONEncoder().encode(projects)
            try data.write(to: url, options: .atomic)
        } catch {
            // Creations are recoverable metadata. A failed write must not interrupt
            // the editing session; the next change retries.
        }
    }
}
